    /** 新版提示沿用已拿到的官方清单，不另发请求；已安装版本和旧版本始终可离线查看。 */
    fun entries(latest: ArenaUpdateInfo?): List<ArenaReleaseNote> {
        if (latest == null || !latest.isNewerThan(BuildConfig.VERSION_CODE) || bundled.any { it.version == latest.versionName }) return bundled
        val changes = latest.notes.lineSequence().map { it.trim() }.filter { it.isNotBlank() }.toList()
        return listOf(ArenaReleaseNote(latest.versionName, latest.releasedAt, "可更新版本", changes.ifEmpty { listOf("该版本尚未提供详细说明。") }, "查看本版主要变化，再按需更新。")) + bundled
    }

    private fun note(version: String, date: String, title: String, vararg changes: String, tryThis: String) =
        ArenaReleaseNote(version, date, title, changes.toList(), tryThis)
}
